package com.huy.enterprise.company;
import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import com.huy.enterprise.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class CompanyService {private final CompanyRepository companies;private final DepartmentRepository departments;private final EmployeeRepository employees;private final UserRepository users; List<CompanyResponse> companies(){return companies.findAll().stream().map(CompanyResponse::from).toList();}@Transactional CompanyResponse company(UUID id,CompanyRequest r){var c=id==null?new Company():companies.findById(id).orElseThrow(()->new ResourceNotFoundException("Company not found: "+id));c.setName(r.name());c.setTaxCode(r.taxCode());c.setEmail(r.email());c.setPhone(r.phone());c.setAddress(r.address());c.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());return CompanyResponse.from(companies.save(c));}List<DepartmentResponse> departments(){return departments.findAll().stream().map(DepartmentResponse::from).toList();}@Transactional DepartmentResponse department(UUID id,DepartmentRequest r){var d=id==null?new Department():departments.findById(id).orElseThrow(()->new ResourceNotFoundException("Department not found: "+id));d.setCompany(companies.findById(r.companyId()).orElseThrow(()->new ResourceNotFoundException("Company not found: "+r.companyId())));d.setName(r.name());d.setCode(r.code());d.setDescription(r.description());d.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());return DepartmentResponse.from(departments.save(d));}List<EmployeeResponse> employees(){return employees.findAll().stream().map(EmployeeResponse::from).toList();}@Transactional EmployeeResponse employee(UUID id,EmployeeRequest r){var e=id==null?new Employee():employees.findById(id).orElseThrow(()->new ResourceNotFoundException("Employee not found: "+id));var c=companies.findById(r.companyId()).orElseThrow(()->new ResourceNotFoundException("Company not found: "+r.companyId()));var d=r.departmentId()==null?null:departments.findById(r.departmentId()).orElseThrow(()->new ResourceNotFoundException("Department not found: "+r.departmentId()));if(d!=null&&!d.getCompany().getId().equals(c.getId()))throw new BusinessException("Department does not belong to company");e.setCompany(c);e.setDepartment(d);e.setUser(r.userId()==null?null:users.findById(r.userId()).orElseThrow(()->new ResourceNotFoundException("User not found: "+r.userId())));e.setEmployeeCode(r.employeeCode());e.setFullName(r.fullName());e.setEmail(r.email());e.setPhone(r.phone());e.setJobTitle(r.jobTitle());e.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());return EmployeeResponse.from(employees.save(e));}}
